# compare styles for all cells that had values in input or answer positions maybe all cells with styles
def style_tuple(c):
    return (c.number_format, c.font.b, c.font.i, c.font.color.rgb if c.font.color else None,
            c.fill.fgColor.rgb if c.fill and c.fill.fgColor else None,
            c.fill.patternType, c.border.left.style, c.border.right.style, c.border.top.style, c.border.bottom.style,
