        for ci in row:
            co=ws_o[ci.coordinate]
            if style_tuple(ci) != style_tuple(co):
                issues.append((ws_i.title,ci.coordinate,style_tuple(ci),style_tuple(co)))
print('style issues', len(issues))
for i in issues[:10]: print(i)
